247	/**
248	 * Run `gh api <path> --paginate` and flatten the concatenated per-page JSON
249	 * arrays into a single array -- the TS equivalent of the common
250	 * `gh api ... --paginate | jq -s 'add // []'` bash idiom. Throws on
251	 * non-zero exit.
252	 */
253	export function ghPaginated<T = unknown>(...args: string[]): T[] {
254	  const { code, stdout, stderr } = gh(...args, "--paginate");
255	  if (code !== 0) {
256	    throw new Error(`gh ${args.join(" ")} --paginate: ${stderr || stdout}`);
257	  }
258	  if (!stdout.trim()) return [];
259	  const flat: T[] = [];
260	  for (const page of splitConcatenatedJson(stdout)) {
261	    if (Array.isArray(page)) flat.push(...(page as T[]));
262	  }
263	  return flat;
264	}
