315	export async function serveMcpServer(options: {
316	  /** Server name reported in the MCP handshake, e.g. `atomaton-web-mcp`. */
317	  name: string;
318	  version: string;
319	  tools: Tool[];
320	  dispatch: McpDispatch;
321	  /** Where this server's diagnostics go. Never stdout: that is the transport. */
322	  log: (message: string) => void;
323	}): Promise<void> {
324	  const server = new Server(
325	    { name: options.name, version: options.version },
326	    { capabilities: { tools: {}, logging: {} } },
327	  );
328	
329	  server.setRequestHandler(ListToolsRequestSchema, async () => ({ tools: options.tools }));
330	
331	  server.setRequestHandler(CallToolRequestSchema, async (request) => {
332	    const { name, arguments: args = {} } = request.params;
333	    try {
334	      const { text, meta, images } = await options.dispatch(name, args);
335	      return {
336	        content: [{ type: "text", text }, ...(images ?? [])],
337	        isError: false,
338	        ...(meta ? { _meta: meta } : {}),
339	      };
340	    } catch (error) {
341	      const message = (error as Error).message ?? String(error);
342	      options.log(`Tool error for ${name}: ${message}`);
343	      return { content: [{ type: "text", text: `Error: ${message}` }], isError: true };
344	    }
345	  });
346	
347	  // When the client says the session is live, not when the socket comes up. A
348	  // notification sent before `initialize` has completed is outside what the protocol
349	  // allows a server to do, and a client is entitled to drop it -- which would make a
350	  // report raised during startup the one report that never arrives, and startup is
351	  // exactly when that happened. Everything said before this moment was held; it goes
352	  // out here, in order.
353	  //
354	  // No `logger` field: atoma names the server that produced a result when it
355	  // attaches the report, so putting the name in as well says it twice.
356	  server.oninitialized = () => {
357	    attachReportChannel((level, message) => {
358	      void server.sendLoggingMessage({ level, data: message }).catch((error) => {
359	        options.log(`could not report (${(error as Error).message}): ${message}`);
360	      });
361	    });
362	  };
363	
364	  await server.connect(new StdioServerTransport());
365	}

