297	/**
298	 * Replace `prefix` on the atomaton-data branch with the contents of `sourceDir`.
299	 *
300	 * Replace, not merge. A file the agent deleted has to be gone next run, or the
301	 * workspace becomes a place where deletions do not take -- the same silent shape
302	 * `unzip -o` produced for `.github/` before `self/` (see
303	 * `tests/contract/self-overlay.test.ts`). `git add --all <prefix>` after removing
304	 * the old tree stages the deletions along with the additions.
305	 *
306	 * The retry loop is `saveSession`'s, for the same reason: sibling agents on
307	 * decomposed issues push to this branch concurrently, and a rejected push means
308	 * someone else got there first rather than that anything is wrong.
309	 */
310	export function saveWorkspace(prefix: string, sourceDir: string, commitMessage: string): boolean {
311	  if (!existsSync(sourceDir)) return true;
312	  if (gitRun("ls-remote", "--exit-code", "origin", DATA_BRANCH).code !== 0) {
313	    // No branch yet means no session has ever been saved either. Leave creating it
314	    // to `saveSession`, which runs in the same job: a workspace with no session is
315	    // not a state worth bringing into existence.
316	    console.error(`[${DATA_BRANCH}] ${DATA_BRANCH} does not exist yet; skipping workspace save`);
317	    return false;
318	  }
319	
320	  gitRun("fetch", "origin", DATA_BRANCH);
321	  const worktreeDir = mkdtempSync(join(tmpdir(), "atomaton-data-ws-"));
322	  gitRun("worktree", "add", worktreeDir, `origin/${DATA_BRANCH}`);
323	
324	  let saved = false;
325	  try {
326	    gitIn(worktreeDir, "config", "user.email", "action@github.com");
327	    gitIn(worktreeDir, "config", "user.name", "GitHub Actions");
328	
329	    for (let attempt = 1; attempt <= 5; attempt++) {
330	      gitIn(worktreeDir, "fetch", "origin", DATA_BRANCH);
331	      gitIn(worktreeDir, "reset", "--hard", `origin/${DATA_BRANCH}`);
332	
333	      const target = join(worktreeDir, prefix);
334	      rmSync(target, { recursive: true, force: true });
335	      mkdirSync(dirname(target), { recursive: true });
336	      cpSync(sourceDir, target, { recursive: true });
337	      gitIn(worktreeDir, "add", "--all", prefix);
338	
339	      if (gitIn(worktreeDir, "diff", "--cached", "--quiet").code === 0) {
340	        saved = true;
341	        break;
342	      }
343	
344	      gitIn(worktreeDir, "commit", "-m", commitMessage);
345	
346	      if (gitIn(worktreeDir, "push", "origin", `HEAD:${DATA_BRANCH}`).code === 0) {
347	        saved = true;
348	        break;
349	      }
350	
351	      console.error(`[${DATA_BRANCH}] workspace push attempt ${attempt} failed (concurrent push) -- retrying`);
352	      Bun.sleepSync(attempt * 2000);
353	    }
354	  } finally {
355	    gitRun("worktree", "remove", "--force", worktreeDir);
356	    rmSync(worktreeDir, { recursive: true, force: true });
357	  }
358	
359	  return saved;
360	}

