 * writing the same path — which would publish one file and report two.
 */
export function resolveDraftFiles(files: { path: string; target: string }[]): DraftFile[] {
  const roots = [resolve(process.cwd()), "/tmp"];
  const seen = new Set<string>();
  const out: DraftFile[] = [];

