/** How to run a command, when the caller needs to add to the environment. */
function runWith(cmd: string[], env?: Record<string, string>): RunResult {
  if (!env) return run(cmd);
  const proc = Bun.spawnSync({
    cmd,
    stdout: "pipe",
    stderr: "pipe",
    // Added to the inherited environment rather than replacing it: these are
    // per-command additions (`GIT_INDEX_FILE`), and a caller that had to restate
    // PATH, HOME and the credential the checkout carries would eventually forget one.
    env: { ...process.env, ...env },
  });
