{"new_string": "/** Run a `git` command. */
export function gitRun(...args: string[]): RunResult {
  return run(["git", ...args]);
}

/** What a caller of `gitRunWith` may add to one invocation. */
export interface GitRunOptions {
  /** Variables added to the inherited environment, for this one process. */
  env?: Record<string, string>;
  /** Text for the command's stdin, when it takes one. */
  stdin?: string;
}

/**
 * Run one `git` command with an added environment and optionally something on stdin.
 *
 * Two callers, and each needed a part `gitRun` cannot express.
 * `machinery/lib/atomaton-data.ts` writes a blob out of a string, which is stdin.
 * `mcp/attachments.ts` publishes onto an orphan branch by building a tree from
 * plumbing, which means `GIT_INDEX_FILE` has to point at a temporary index — and it
 * does NOT mean assigning to `process.env`: that variable would stay set for every
 * later `git` in the same process, including a `commit_and_push` the agent makes
 * afterwards, and the run's own index would silently be a tree of drafts.
 *
 * The environment is ADDED to rather than replacing it. A command that had to restate
 * PATH, HOME and whatever `actions/checkout` left in `.git/config` is a command that
 * will eventually restate one of them wrongly.
 */
export function gitRunWith(options: GitRunOptions, ...args: string[]): RunResult {
  const proc = Bun.spawnSync({
    cmd: ["git", ...args],
    stdout: "pipe",
    stderr: "pipe",
    ...(options.stdin !== undefined ? { stdin: Buffer.from(options.stdin) } : {}),
    ...(options.env ? { env: { ...process.env, ...options.env } } : {}),
  });
