const SCRIPTS_DIR = join(process.cwd(), "src/entrypoints/tools/mcp");

function sendRequest(script: string, request: Record<string, unknown>, env: Record<string, string> = {}, cwd = process.cwd(), timeoutMs = 20_000): Promise<any> {
  return new Promise((resolve, reject) => {
    const child = spawn(process.execPath, ["run", `${SCRIPTS_DIR}/${script}`], { env: { ...hermeticEnv(), GITHUB_REPOSITORY: "owner/repo", ...env }, cwd });
    let out = "", err = "";
    child.stderr.on("data", (d) => (err += d.toString()));
    const timer = setTimeout(() => { child.kill(); reject(new Error(`timeout; stderr=${err}`)); }, timeoutMs);
    child.stdout.on("data", (d) => {
      out += d.toString();
      const line = out.split("\n").find((l) => l.trim());
      if (!line) return;
      clearTimeout(timer);
      child.kill();
      try { resolve(JSON.parse(line)); } catch (e) { reject(e); }
    });
    child.stdin.write(JSON.stringify(request) + "\n");
  });
}

