  defineMcpTool({
    name: "publish_draft",
    description: PUBLISH_DRAFT_DESCRIPTION,
    schema: PUBLISH_DRAFT_SCHEMA,
    handler: publishDraft,
  }),
]);

async function main(): Promise<void> {
  await serveMcpServer({ name: "atomaton-attachments-mcp", version: "1.0.0", tools, dispatch, log });
