43	function measure(root: string): WorkspaceUsage {
44	  const usage: WorkspaceUsage = { bytes: 0, files: 0, largest: [] };
45	  const stack = [root];
46	
47	  while (stack.length > 0 && usage.files < WALK_CEILING) {
48	    const dir = stack.pop()!;
49	    let entries;
50	    try {
51	      entries = readdirSync(dir, { withFileTypes: true });
52	    } catch {
53	      // A directory that cannot be read is not a reason to say anything: the
54	      // workspace may simply not exist yet, which is the common case.
55	      continue;
56	    }
57	    for (const entry of entries) {
58	      if (usage.files >= WALK_CEILING) break;
59	      const path = join(dir, entry.name);
60	      if (entry.isDirectory()) {
61	        stack.push(path);
62	        continue;
63	      }
64	      // Symlinks are counted as the link, not as what they point at: following them
65	      // would let one into a size that is not in the workspace at all, and would
66	      // loop on a cycle.
67	      if (!entry.isFile()) continue;
68	      let size;
69	      try {
70	        size = statSync(path).size;
71	      } catch {
72	        continue;
73	      }
74	      usage.files += 1;
75	      usage.bytes += size;
